from ortools.sat.python import cp_model
import itertools
import json

def main():
    model = cp_model.CpModel()

    workflows = ['Alpha', 'Beta', 'Gamma', 'Delta']
    hardware = ['GPU-Cluster', 'CPU-Node', 'Memory-Array', 'I/O-Subsystem']

    processing_time = {
        'Alpha': {
            'GPU-Cluster': 54,
            'CPU-Node': 34,
            'Memory-Array': 61,
            'I/O-Subsystem': 2
        },
        'Beta': {
            'GPU-Cluster': 70,
            'CPU-Node': 15,
            'Memory-Array': 9,
            'I/O-Subsystem': 89
        },
        'Gamma': {
            'GPU-Cluster': 28,
            'CPU-Node': 38,
            'Memory-Array': 87,
            'I/O-Subsystem': 19
        },
        'Delta': {
            'GPU-Cluster': 34,
            'CPU-Node': 95,
            'Memory-Array': 29,
            'I/O-Subsystem': 7
        }
    }

    total_time = sum(processing_time[w][h] for w in workflows for h in hardware)

    start = {}
    for w in workflows:
        for h in hardware:
            start[(w, h)] = model.NewIntVar(0, total_time, f'start_{w}_{h}')

    makespan = model.NewIntVar(0, total_time, 'makespan')

    for w in workflows:
        for h1, h2 in itertools.combinations(hardware, 2):
            task1_before_task2 = model.NewBoolVar(f'{w}_{h1}_before_{h2}')
            task2_before_task1 = model.NewBoolVar(f'{w}_{h2}_before_{h1}')

            model.AddBoolOr([task1_before_task2, task2_before_task1])
            model.AddImplication(task1_before_task2, task2_before_task1.Not())
            model.AddImplication(task2_before_task1, task1_before_task2.Not())

            model.Add(start[(w, h1)] + processing_time[w][h1] <= start[(w, h2)]) \
                .OnlyEnforceIf(task1_before_task2)

            model.Add(start[(w, h2)] + processing_time[w][h2] <= start[(w, h1)]) \
                .OnlyEnforceIf(task2_before_task1)

    for h in hardware:
        for w1, w2 in itertools.combinations(workflows, 2):
            w1_before_w2 = model.NewBoolVar(f'{h}_{w1}_before_{w2}')
            w2_before_w1 = model.NewBoolVar(f'{h}_{w2}_before_{w1}')

            model.AddBoolOr([w1_before_w2, w2_before_w1])
            model.AddImplication(w1_before_w2, w2_before_w1.Not())
            model.AddImplication(w2_before_w1, w1_before_w2.Not())

            model.Add(start[(w1, h)] + processing_time[w1][h] <= start[(w2, h)]) \
                .OnlyEnforceIf(w1_before_w2)

            model.Add(start[(w2, h)] + processing_time[w2][h] <= start[(w1, h)]) \
                .OnlyEnforceIf(w2_before_w1)

    for w in workflows:
        for h in hardware:
            model.Add(start[(w, h)] + processing_time[w][h] <= makespan)

    model.Minimize(makespan)

    solver = cp_model.CpSolver()
    solver.parameters.max_time_in_seconds = 30.0
    solver.parameters.num_search_workers = 8

    status = solver.Solve(model)

    if status in (cp_model.OPTIMAL, cp_model.FEASIBLE):
        start_times = []
        for w in workflows:
            workflow_times = []
            for h in hardware:
                workflow_times.append(solver.Value(start[(w, h)]))
            start_times.append(workflow_times)

        result = {
            "start_times": start_times,
            "makespan": solver.Value(makespan)
        }
        print(json.dumps(result))
    else:
        result = {
            "start_times": [],
            "makespan": 0
        }
        print(json.dumps(result))

if __name__ == '__main__':
    main()
